    const parse = (r) => Date.parse(String(r.ts || "").replace(" ", "T"));
    const stamps = rows.map(parse).filter((t) => !Number.isNaN(t));
    const newest = stamps.length ? Math.max.apply(null, stamps) : null;
    const STALE_MS = 4 * DAY_MS;
